window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bf191fbb35032f36"]={"versions": [{"id": "FIG-bf191fbb35032f36", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P07mCheck</code> (Server-Overload-Variante) innerhalb der AUTOSAR-E2E-Bibliothek (End-to-End Communication Protection, Profile 7m).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktionsschnittstelle: <code>E2E_P07mCheck(Config, State, SourceID, MessageTyp, MessageResult, Data, Length)</code> (im Diagrammkopf abgeschnitten dargestellt als <code>E2E_P07mCheck(Config, State, SourceID, MessageTyp, MessageResult, Data,</code>)</li>\n<li>Unteraktivitäten / Call-Behavior-Aktionen (mit Refinement-Symbol):</li>\n<li><code>Verify inputs of the check function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read SourceID</code></li>\n<li><code>Read Message Type</code></li>\n<li><code>Read Message Result</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Do checks</code></li>\n<li>Entscheidungsknoten (Decision Node): Verzweigung nach Bedingung <code>NewDataAvailable == TRUE</code> mit den Guards <code>[TRUE]</code> und <code>[FALSE]</code></li>\n<li>Kontrollfluss-Verzweigungen bei Eingabeprüfung: Guards <code>[input ok]</code>, <code>[null input]</code> und <code>[wrong input]</code></li>\n<li>Ablaufendknoten (Activity Final Nodes): Drei Endknoten mit Rückgaben (<code>return</code>), korrespondierend zu den Fehlerpfaden und dem regulären Prüfpfad.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start am Initialknoten beim Aufruf von <code>E2E_P07mCheck</code>.</li>\n<li>Ausführung der Eingabevalidierung in <code>Verify inputs of the check function</code>.</li>\n<li>Verzweigung anhand des Validierungsergebnisses:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[null input]</code>: Direkter Übergang zum linken Endknoten (Rückgabe des Fehlers für Null-Pointer).</li>\n<li>Bei <code>[wrong input]</code>: Direkter Übergang zum rechten Endknoten (Rückgabe des Fehlers für ungültige Parameter).</li>\n<li>Bei <code>[input ok]</code>: Übergang zur Auswertung der Bedingung <code>NewDataAvailable == TRUE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Entscheidung an der Bedingung <code>NewDataAvailable == TRUE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[TRUE]</code>: Sequenzielle Abarbeitung der Schritte:</li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read SourceID</code></li>\n<li><code>Read Message Type</code></li>\n<li><code>Read Message Result</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li>Anschließend Übergang zu <code>Do checks</code>.</li>\n<li>Zweig <code>[FALSE]</code>: Umgehung der Lese- und CRC-Berechnungsschritte über einen Bypass direkt zu <code>Do checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Ausführung von <code>Do checks</code> und abschließender Übergang zum mittleren Endknoten (<code>return</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation des Gesamtverhaltens der Server-Overload-Funktion <code>E2E_P07mCheck()</code> gemäß <code>[PRS_E2E_00841]</code>.</p>\n<p class=\"fig-p\">Entwickler-Hinweise zur Implementierung:</p>\n<ul class=\"fig-list\">\n<li>Streng deterministische Fehlerabfangung: Vor jeder Datenverarbeitung müssen Parameter auf Nullzeiger (<code>[null input]</code>) und Wertebereichsgrenzen (<code>[wrong input]</code>) geprüft werden; bei Fehlern bricht die Funktion sofort ohne Zustands- oder Datenveränderung ab.</li>\n<li>Wenn keine neuen Daten anliegen (<code>NewDataAvailable == FALSE</code>), werden weder Header-Felder extrahiert noch CRCs gerechnet, sondern direkt die E2E-Zustandsprüfungen (<code>Do checks</code>) ausgeführt.</li>\n<li>Bei Vorliegen neuer Daten (<code>NewDataAvailable == TRUE</code>) ist die Extraktion der Profil-7m-spezifischen Header-Felder (Länge, Counter, DataID, SourceID, Message Type, Message Result, CRC) sowie die CRC-Prüfsummenberechnung vor der finalen Bewertung zwingend vorgeschrieben.</li>\n</ul>"}, {"id": "FIG-32b9a7324c30dae4", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P07mCheck</code> (Server-Overload-Variante) innerhalb der AUTOSAR-E2E-Bibliothek (End-to-End Communication Protection, Profile 7m).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktionsschnittstelle: <code>E2E_P07mCheck(Config, State, SourceID, MessageTyp, MessageResult, Data, Length)</code> (im Diagrammkopf abgeschnitten dargestellt als <code>E2E_P07mCheck(Config, State, SourceID, MessageTyp, MessageResult, Data,</code>)</li>\n<li>Unteraktivitäten / Call-Behavior-Aktionen (mit Refinement-Symbol):</li>\n<li><code>Verify inputs of the check function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read SourceID</code></li>\n<li><code>Read Message Type</code></li>\n<li><code>Read Message Result</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Do checks</code></li>\n<li>Entscheidungsknoten (Decision Node): Verzweigung nach Bedingung <code>NewDataAvailable == TRUE</code> mit den Guards <code>[TRUE]</code> und <code>[FALSE]</code></li>\n<li>Kontrollfluss-Verzweigungen bei Eingabeprüfung: Guards <code>[input ok]</code>, <code>[null input]</code> und <code>[wrong input]</code></li>\n<li>Ablaufendknoten (Activity Final Nodes): Drei Endknoten mit Rückgaben (<code>return</code>), korrespondierend zu den Fehlerpfaden und dem regulären Prüfpfad.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start am Initialknoten beim Aufruf von <code>E2E_P07mCheck</code>.</li>\n<li>Ausführung der Eingabevalidierung in <code>Verify inputs of the check function</code>.</li>\n<li>Verzweigung anhand des Validierungsergebnisses:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[null input]</code>: Direkter Übergang zum linken Endknoten (Rückgabe des Fehlers für Null-Pointer).</li>\n<li>Bei <code>[wrong input]</code>: Direkter Übergang zum rechten Endknoten (Rückgabe des Fehlers für ungültige Parameter).</li>\n<li>Bei <code>[input ok]</code>: Übergang zur Auswertung der Bedingung <code>NewDataAvailable == TRUE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Entscheidung an der Bedingung <code>NewDataAvailable == TRUE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[TRUE]</code>: Sequenzielle Abarbeitung der Schritte:</li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read SourceID</code></li>\n<li><code>Read Message Type</code></li>\n<li><code>Read Message Result</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li>Anschließend Übergang zu <code>Do checks</code>.</li>\n<li>Zweig <code>[FALSE]</code>: Umgehung der Lese- und CRC-Berechnungsschritte über einen Bypass direkt zu <code>Do checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Ausführung von <code>Do checks</code> und abschließender Übergang zum mittleren Endknoten (<code>return</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation des Gesamtverhaltens der Server-Overload-Funktion <code>E2E_P07mCheck()</code> gemäß <code>[PRS_E2E_00841]</code>.</p>\n<p class=\"fig-p\">Entwickler-Hinweise zur Implementierung:</p>\n<ul class=\"fig-list\">\n<li>Streng deterministische Fehlerabfangung: Vor jeder Datenverarbeitung müssen Parameter auf Nullzeiger (<code>[null input]</code>) und Wertebereichsgrenzen (<code>[wrong input]</code>) geprüft werden; bei Fehlern bricht die Funktion sofort ohne Zustands- oder Datenveränderung ab.</li>\n<li>Wenn keine neuen Daten anliegen (<code>NewDataAvailable == FALSE</code>), werden weder Header-Felder extrahiert noch CRCs gerechnet, sondern direkt die E2E-Zustandsprüfungen (<code>Do checks</code>) ausgeführt.</li>\n<li>Bei Vorliegen neuer Daten (<code>NewDataAvailable == TRUE</code>) ist die Extraktion der Profil-7m-spezifischen Header-Felder (Länge, Counter, DataID, SourceID, Message Type, Message Result, CRC) sowie die CRC-Prüfsummenberechnung vor der finalen Bewertung zwingend vorgeschrieben.</li>\n</ul>"}], "trans": [{"from": "FIG-bf191fbb35032f36", "to": "FIG-32b9a7324c30dae4", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
